"""提示词模板与变量：可复用变量代入多段提示词。

QQ-提示词变量 维护一张 {名称: 值} 变量表（序列化为 JSON 字符串输出）；
QQ-提示词模板 把模板里的 {名称} 用变量值替换，支持 {名称:默认值} 缺省回退，
{{ / }} 转义为字面花括号。未解析的 token 原样保留，便于发现漏配的变量。
"""

from __future__ import annotations

import json
from typing import Any


def parse_variables(raw: Any) -> dict[str, str]:
    """把变量节点输出的 JSON 解析成字典；损坏时回退空表，绝不抛错。"""
    if isinstance(raw, dict):
        return {str(k): str(v) for k, v in raw.items()}
    text = str(raw or "").strip()
    if not text:
        return {}
    try:
        data = json.loads(text)
    except (ValueError, TypeError):
        return {}
    if not isinstance(data, dict):
        return {}
    return {str(k): str(v) for k, v in data.items()}


def resolve_template(template: str, variables: dict[str, Any] | None) -> tuple[str, list[str]]:
    """单趟扫描替换 {名称} / {名称:默认值}，返回 (渲染文本, 未解析名称列表)。

    {{ 与 }} 输出字面花括号；没有闭合 } 的残段原样保留。
    """
    variables = variables or {}
    text = str(template or "")
    out: list[str] = []
    unresolved: list[str] = []
    index = 0
    length = len(text)
    while index < length:
        char = text[index]
        if char == "{" and index + 1 < length and text[index + 1] == "{":
            out.append("{")
            index += 2
            continue
        if char == "}" and index + 1 < length and text[index + 1] == "}":
            out.append("}")
            index += 2
            continue
        if char == "{":
            close = text.find("}", index + 1)
            if close == -1:
                out.append(text[index:])
                break
            token = text[index + 1 : close]
            name, sep, default = token.partition(":")
            name = name.strip()
            if name in variables:
                out.append(str(variables[name]))
            elif sep:
                out.append(default)
            else:
                out.append(text[index : close + 1])
                if name and name not in unresolved:
                    unresolved.append(name)
            index = close + 1
            continue
        out.append(char)
        index += 1
    return "".join(out), unresolved


class QQPromptVariables:
    """变量表节点：前端 DOM 面板编辑，JSON 字符串输出供模板节点消费。"""

    CATEGORY = "QQ/工具"
    FUNCTION = "emit"
    RETURN_TYPES = ("STRING",)
    RETURN_NAMES = ("变量",)
    DESCRIPTION = (
        "维护一张 {名称:值} 变量表，输出 JSON 字符串。接到 QQ-提示词模板 的「变量」口，"
        "模板里的 {名称} 会被替换成对应值；改一处变量，所有引用它的模板同步生效。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "变量JSON": ("STRING", {"default": "{}", "multiline": False}),
            },
        }

    @staticmethod
    def emit(变量JSON: str = "{}", **_kwargs: Any):
        # 原样透传；解析与容错由模板节点负责，保证变量节点本身永不报错。
        return (str(变量JSON or "{}"),)


class QQPromptTemplate:
    """模板节点：{名称} 代入变量，支持缺省回退与转义。"""

    CATEGORY = "QQ/工具"
    FUNCTION = "render"
    RETURN_TYPES = ("STRING",)
    RETURN_NAMES = ("文本",)
    DESCRIPTION = (
        "把模板里的 {名称} 用变量值替换；{名称:默认值} 在变量缺失时用默认值；"
        "{{ / }} 输出字面花括号。可选接入变量表与 文本1/文本2（作为 {文本1}/{文本2}）。"
        "未解析的 token 原样保留。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "模板": ("STRING", {"default": "{角色} 在 {场景}", "multiline": True}),
            },
            "optional": {
                "变量": ("STRING", {"forceInput": True}),
                "文本1": ("STRING", {"forceInput": True}),
                "文本2": ("STRING", {"forceInput": True}),
            },
        }

    @staticmethod
    def render(模板: str = "", 变量: Any = None, 文本1: Any = None, 文本2: Any = None, **_kwargs: Any):
        variables = parse_variables(变量)
        if 文本1 is not None:
            variables["文本1"] = str(文本1)
        if 文本2 is not None:
            variables["文本2"] = str(文本2)
        text, _unresolved = resolve_template(模板, variables)
        return (text,)


NODE_CLASS_MAPPINGS = {
    "QQPromptVariables": QQPromptVariables,
    "QQPromptTemplate": QQPromptTemplate,
}
NODE_DISPLAY_NAME_MAPPINGS = {
    "QQPromptVariables": "QQ-提示词变量",
    "QQPromptTemplate": "QQ-提示词模板",
}
